Datetime winter = Datetime.valueOfGmt('2024-02-29T23:59:58Z');
Datetime summer = Datetime.valueOfGmt('2024-07-01T12:00:00Z');
System.assertEquals(-21600000, TimeZone.getTimeZone('America/Chicago').getOffset(winter));
System.assertEquals(-18000000, TimeZone.getTimeZone('America/Chicago').getOffset(summer));
System.assertEquals(-25200000, TimeZone.getTimeZone('America/Denver').getOffset(winter));
System.assertEquals(-21600000, TimeZone.getTimeZone('America/Denver').getOffset(summer));
System.assertEquals(0, TimeZone.getTimeZone('Europe/London').getOffset(winter));
System.assertEquals(3600000, TimeZone.getTimeZone('Europe/London').getOffset(summer));
System.assertEquals(3600000, TimeZone.getTimeZone('Europe/Berlin').getOffset(winter));
System.assertEquals(7200000, TimeZone.getTimeZone('Europe/Berlin').getOffset(summer));
System.assertEquals(32400000, TimeZone.getTimeZone('Asia/Tokyo').getOffset(winter));
System.assertEquals(32400000, TimeZone.getTimeZone('Asia/Tokyo').getOffset(summer));
System.assertEquals(39600000, TimeZone.getTimeZone('Australia/Sydney').getOffset(winter));
System.assertEquals(36000000, TimeZone.getTimeZone('Australia/Sydney').getOffset(summer));

